	@Test
	void socialMediaCachedProjectionReplaysWithoutPayloadInvariantFallback() throws Exception {
		Logger logger = (Logger) LoggerFactory.getLogger(LmdbCascadesOptimizer.class);
		assertTrue(logger.isWarnEnabled(), "planner warnings must be observable during the test");
		ListAppender<ILoggingEvent> appender = new ListAppender<>();
		List<String> failures = new ArrayList<>();
		Map<Integer, ObservedResult> generic = new HashMap<>();
		Map<Integer, ObservedResult> nativeEnabled = new HashMap<>();
		Bundle expected = loadBundle(ThemeOracleProfile.SOCIAL_MEDIA);
		String threadName = Thread.currentThread().getName();
		appender.start();
		logger.addAppender(appender);
		try {
			assertCatalogParity(ThemeOracleProfile.SOCIAL_MEDIA,
					(repository, query, nativeEngine, index, arm, fixture) -> {
						int start;
						synchronized (appender) {
							start = appender.list.size();
						}
						ObservedResult result;
						try {
							result = evaluate(repository, query, nativeEngine, index, arm, fixture);
						} finally {
							List<ILoggingEvent> events;
							synchronized (appender) {
								events = List.copyOf(appender.list.subList(start, appender.list.size()));
							}
							for (ILoggingEvent event : events) {
								if (threadName.equals(event.getThreadName()) && isPackedPayloadReplayFailure(event)) {
									failures.add("query=" + index + " arm=" + arm + ": " + event.getFormattedMessage());
								}
							}
						}
						if (index == 11 || index == 12) {
							if ("lmdb-generic".equals(arm)) {
								generic.put(index, result);
							} else if ("lmdb-native-enabled".equals(arm)) {
								nativeEnabled.put(index, result);
							}
						}
						return result;
					});
			for (int index : List.of(11, 12)) {
				QueryGolden golden = expected.queries().get(index);
				assertTrue(golden.computedNumericVariables().isEmpty(), "exact golden required for q" + index);
				assertTrue(generic.containsKey(index), "generic q" + index + " was not evaluated");
				assertTrue(nativeEnabled.containsKey(index), "native-enabled q" + index + " was not evaluated");
				assertBagsEqual(golden.bag(), generic.get(index).bag(), "generic q" + index);
				assertBagsEqual(golden.bag(), nativeEnabled.get(index).bag(), "native-enabled q" + index);
				assertOrderIfPinned(golden, generic.get(index), "generic q" + index);
				assertOrderIfPinned(golden, nativeEnabled.get(index), "native-enabled q" + index);
			}
			assertTrue(failures.isEmpty(), () -> "packed cached projection payload invariant fallback: " + failures);
		} finally {
			logger.detachAppender(appender);
			appender.stop();
		}
	}

	private static boolean isPackedPayloadReplayFailure(ILoggingEvent event) {
		IThrowableProxy failure = event.getThrowableProxy();
		if (event.getLevel() != Level.WARN || failure == null || !failure.getClassName()
				.equals("org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed.PackedMemoInvariantException")) {
			return false;
		}
		var frames = Arrays.stream(failure.getStackTraceElementProxyArray())
				.map(proxy -> proxy.getStackTraceElement())
				.toList();
		return frames.stream()
				.anyMatch(frame -> frame.getClassName().endsWith(".PackedPlanMaterializer")
						&& frame.getMethodName().equals("requirePayload"))
				&& frames.stream()
						.anyMatch(frame -> frame.getClassName().endsWith(".PackedCascadesPlanner")
								&& frame.getMethodName().equals("cachedResult"));
	}

