	private void assertCatalogParity(ThemeOracleProfile fixture) throws Exception {
		assertCatalogParity(fixture, LmdbRealEstateExactBagParityTest::evaluate);
	}

	private void assertCatalogParity(ThemeOracleProfile fixture, EvaluationRunner runner) throws Exception {
		Bundle bundle = loadBundle(fixture);
		List<BenchmarkQuery> queries = ThemeQueryCatalog.benchmarkQueriesFor(fixture.theme());
		assertEquals(13, ThemeQueryCatalog.QUERY_COUNT);
		assertEquals(13, queries.size());

		SailRepository memory = new SailRepository(new MemoryStore());
		SailRepository lmdb = new SailRepository(new LmdbStore(temporaryDirectory.resolve("lmdb").toFile(),
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true).setForceSync(false)));
		try {
			loadDataset(memory, bundle.dataset(), fixture);
			loadDataset(lmdb, bundle.dataset(), fixture);
			for (int index = 0; index < queries.size(); index++) {
				BenchmarkQuery query = queries.get(index);
				QueryGolden golden = bundle.queries().get(index);
				assertEquals(index, golden.index(), "golden query index");
				assertEquals(query.getName(), golden.name(), "golden query name at index " + index);
				assertEquals(sha256(query.getQuery().getBytes(StandardCharsets.UTF_8)), golden.querySha256(),
						"catalog query text identity at index " + index);
				var parsed = new SPARQLParser().parseQuery(query.getQuery(), null).getTupleExpr();
				fixture.requireSupportedOrder(index, parsed);
				ComputedNumericBagPolicy.Plan comparison = ComputedNumericBagPolicy.prove(parsed,
						golden.bag().variableNames());
				assertEquals(golden.computedNumericVariables(),
						comparison.computedVariables().stream().sorted().toList(),
						"independently proven computed numeric variables at index " + index);

				ObservedResult memoryRows = runner.evaluate(memory, query.getQuery(), false, index, "memory", fixture);
				ObservedResult lmdbGenericRows = runner.evaluate(lmdb, query.getQuery(), false, index, "lmdb-generic",
						fixture);
				ObservedResult lmdbNativeRows = runner.evaluate(lmdb, query.getQuery(), true, index,
						"lmdb-native-enabled",
						fixture);
				String context = fixture.theme() + " query " + index + " (" + query.getName() + "): ";
				assertJenaBagsEquivalent(golden.bag(), memoryRows.bag(), comparison, context + "MemoryStore/Jena");
				assertJenaBagsEquivalent(golden.bag(), lmdbGenericRows.bag(), comparison,
						context + "LMDB generic/Jena");
				assertJenaBagsEquivalent(golden.bag(), lmdbNativeRows.bag(), comparison, context + "LMDB native/Jena");
				assertBagsEqual(memoryRows.bag(), lmdbGenericRows.bag(), context + "MemoryStore/LMDB generic");
				assertBagsEqual(lmdbGenericRows.bag(), lmdbNativeRows.bag(), context + "LMDB generic/native");
				assertOrderIfPinned(golden, memoryRows, context + "MemoryStore");
				assertOrderIfPinned(golden, lmdbGenericRows, context + "LMDB generic");
				assertOrderIfPinned(golden, lmdbNativeRows, context + "LMDB native");
				System.out.println(
						fixture.theme() + "_BAG_PASS query=" + index + " rows=" + golden.bag().totalMultiplicity());
			}
		} finally {
			lmdb.shutDown();
			memory.shutDown();
		}
	}

	@Test
	void rejectsMalformedIntegerIdentitiesAndCountsInManifest() throws Exception {
		ObjectNode original = (ObjectNode) JSON.readTree(requiredResource("manifest.json"));
		assertDoesNotThrow(() -> loadBundle(original));
		List<ManifestMutation> mutations = List.of(
				new ManifestMutation("bundle version fraction", root -> root.put("version", 2.5)),
				new ManifestMutation("bundle version overflow", root -> root.put("version", 4_294_967_298L)),
				new ManifestMutation("codec version fraction", root -> object(root, "codec").put("version", 1.5)),
				new ManifestMutation("codec version overflow",
						root -> object(root, "codec").put("version", 4_294_967_297L)),
				new ManifestMutation("dataset byte count fraction",
						root -> object(root, "dataset").put("bytes", 86583.5)),
				new ManifestMutation("dataset statement count fraction",
						root -> object(root, "dataset").put("statements", 522.5)),
				new ManifestMutation("fixture seed fraction", root -> object(root, "fixture").put("seed", 42.5)),
				new ManifestMutation("requested count fraction",
						root -> object(object(root, "fixture"), "requestedCounts").put("districts", 4.5)),
				new ManifestMutation("missing zero seeded count",
						root -> object(object(root, "fixture"), "seededActualCounts").remove("viewing")),
				new ManifestMutation("fixture count fraction",
						root -> object(object(root, "fixture"), "fixtureActualCounts").put("district", 21.5)),
				new ManifestMutation("unsupported graph scope",
						root -> object(object(root, "fixture"), "scope").put("graphs", "named-graphs")),
				new ManifestMutation("unsupported directional scope",
						root -> object(object(root, "fixture"), "scope").put("directionalLiterals", true)),
				new ManifestMutation("fractional statement count",
						root -> object(root, "fixture").put("statementCount", 522.5)),
				new ManifestMutation("missing zero query index", root -> query(root, 0).remove("index")),
				new ManifestMutation("fractional query index", root -> query(root, 0).put("index", 0.5)),
				new ManifestMutation("overflow query index", root -> query(root, 0).put("index", 4_294_967_296L)),
				new ManifestMutation("fractional result count", root -> query(root, 0).put("rows", 2.5)),
				new ManifestMutation("fractional distinct rows", root -> query(root, 0).put("distinctRows", 2.5)),
				new ManifestMutation("wrong distinct rows", root -> query(root, 0).put("distinctRows", 3)));
		assertAll(mutations.stream().map(mutation -> () -> {
			ObjectNode changed = original.deepCopy();
			mutation.edit().accept(changed);
			assertThrows(AssertionError.class, () -> loadBundle(changed), mutation.name());
		}));
	}

