	@Test
	void detachingRejectsMalformedLiteralMetadataAtEveryNestedDepth() {
		List<Literal> malformed = List.of(
				new TestLiteral("value", XSD.STRING, Optional.of("en"), Literal.BaseDirection.NONE),
				new TestLiteral("value", RDF.LANGSTRING, Optional.of("en"), Literal.BaseDirection.LTR),
				new TestLiteral("value", RDF.DIRLANGSTRING, Optional.of("en"), Literal.BaseDirection.NONE),
				new TestLiteral("value", XSD.STRING, Optional.empty(), Literal.BaseDirection.RTL));
		List<Literal> valid = List.of(VALUE_FACTORY.createLiteral("value", "en"),
				VALUE_FACTORY.createLiteral("value", "en", Literal.BaseDirection.LTR),
				VALUE_FACTORY.createLiteral("value", "he", Literal.BaseDirection.RTL));
		List<Executable> checks = new ArrayList<>();
		for (int depth = 0; depth < 3; depth++) {
			final int nesting = depth;
			for (Literal literal : valid) {
				Value value = wrap(literal, nesting);
				assertEquals(value, detach(value), "valid metadata at depth " + nesting);
			}
			for (Literal literal : malformed) {
				Value value = wrap(literal, nesting);
				checks.add(() -> assertThrows(AssertionError.class, () -> detach(value),
						"inconsistent " + literal.getDatatype() + " at depth " + nesting));
			}
		}
		assertAll(checks);
	}

	private static Value wrap(Value value, int depth) {
		Value result = value;
		for (int i = 0; i < depth; i++) {
			result = VALUE_FACTORY.createTripleTerm(VALUE_FACTORY.createIRI("urn:subject"),
					VALUE_FACTORY.createIRI("urn:predicate"), result);
		}
		return result;
	}

	private static final class TestLiteral extends AbstractLiteral {
		private static final long serialVersionUID = 1L;
		private final String label;
		private final IRI datatype;
		private final Optional<String> language;
		private final BaseDirection direction;

		private TestLiteral(String label, IRI datatype, Optional<String> language, BaseDirection direction) {
			this.label = label;
			this.datatype = datatype;
			this.language = language;
			this.direction = direction;
		}

		@Override
		public String getLabel() {
			return label;
		}

		@Override
		public IRI getDatatype() {
			return datatype;
		}

		@Override
		public CoreDatatype getCoreDatatype() {
			return CoreDatatype.from(datatype);
		}

		@Override
		public Optional<String> getLanguage() {
			return language;
		}

		@Override
		public BaseDirection getBaseDirection() {
			return direction;
		}
	}

	private record ManifestMutation(String name, Consumer<ObjectNode> edit) {
	}

	private static ObjectNode object(ObjectNode parent, String field) {
		return (ObjectNode) parent.path(field);
	}

	private static ObjectNode query(ObjectNode root, int index) {
		return (ObjectNode) root.path("queries").get(index);
	}

	private static Bundle loadBundle(ThemeOracleProfile fixture) throws IOException {
		return loadBundle(fixture, JSON.readTree(requiredResource(fixture, "manifest.json")));
	}

	private static Bundle loadBundle(JsonNode manifest) throws IOException {
		return loadBundle(ThemeOracleProfile.REAL_ESTATE, manifest);
	}

	private static Bundle loadBundle(ThemeOracleProfile fixture, JsonNode manifest) throws IOException {
		assertEquals(fixture.format(), manifest.path("format").asText(), "required oracle bundle format");
		assertEquals(fixture.version(), requiredInt(manifest, "version"), "required oracle bundle version");
		if (fixture.themeRequired() || manifest.has("theme")) {
			assertEquals(fixture.theme().name(), manifest.path("theme").asText(), "oracle bundle theme");
		}
		JsonNode codec = manifest.path("codec");
		assertEquals(SolutionBagCodec.FORMAT_ID, codec.path("format").asText(), "solution bag format identity");
		assertEquals(SolutionBagCodec.FORMAT_VERSION, requiredInt(codec, "version"), "solution bag version");
		JsonNode comparison = manifest.path("comparisonPolicy");
		assertEquals(ComputedNumericBagPolicy.POLICY_ID, comparison.path("id").asText(), "comparison policy identity");
		assertEquals(ComputedNumericBagPolicy.POLICY_VERSION, requiredInt(comparison, "version"),
				"comparison policy version");
		JsonNode jena = manifest.path("jena");
		assertEquals("org.apache.jena:jena-arq", jena.path("artifact").asText(), "independent Jena artifact");
		assertEquals(JENA_VERSION, jena.path("version").asText(), "independent Jena version");
		assertTrue(jena.path("jarSha256").asText().matches("[0-9a-f]{64}"), "Jena jar identity must be pinned");

		byte[] dataset = requiredResource(fixture, "dataset.nq");
		JsonNode datasetRecord = manifest.path("dataset");
		assertEquals("dataset.nq", datasetRecord.path("file").asText());
		assertEquals("N-Quads", datasetRecord.path("format").asText());
		assertEquals(dataset.length, requiredCount(datasetRecord, "bytes"), "dataset byte count");
		assertEquals(sha256(dataset), datasetRecord.path("sha256").asText(), "dataset SHA-256");
		assertEquals(fixture.datasetSha256(), sha256(dataset), "independently pinned dataset SHA-256");
		switch (fixture.fixtureSchema()) {
		case REAL_ESTATE_V2 -> validateFixtureCounts(manifest.path("fixture"), datasetRecord);
		case SOCIAL_MEDIA_V2 -> validateSocialFixtureCounts(manifest.path("fixture"), datasetRecord);
		case DEFAULT_GRAPH_V1 -> validateDefaultFixture(fixture, manifest.path("fixture"), datasetRecord);
		}

		JsonNode queryRecords = manifest.path("queries");
		assertTrue(queryRecords.isArray(), "bundle query records must be an array");
		assertEquals(13, queryRecords.size(), "bundle must require all 13 catalog cells");
		ArrayList<QueryGolden> goldens = new ArrayList<>(queryRecords.size());
		for (int index = 0; index < queryRecords.size(); index++) {
			JsonNode queryRecord = queryRecords.get(index);
			String bagFile = String.format(Locale.ROOT, "query-%02d.json", index);
			assertEquals(index, requiredInt(queryRecord, "index"), "manifest query order");
			assertEquals(bagFile, queryRecord.path("bagFile").asText(), "manifest query bag path");
			byte[] bagBytes = requiredResource(fixture, "queries/" + bagFile);
			assertEquals(sha256(bagBytes), queryRecord.path("bagSha256").asText(), "query bag SHA-256 " + index);
			Bag bag = SolutionBagCodec.decode(new String(bagBytes, StandardCharsets.UTF_8));
			assertEquals(requiredCount(queryRecord, "rows"), bag.totalMultiplicity(),
					"expected query result multiplicity " + index);
			assertEquals(requiredCount(queryRecord, "distinctRows"), bag.rows().size(),
					"expected distinct query rows " + index);
			JsonNode numericVariables = queryRecord.path("computedNumericVariables");
			assertTrue(numericVariables.isArray(), "computed numeric proof must be an array at index " + index);
			ArrayList<String> computedVariables = new ArrayList<>();
			numericVariables.forEach(value -> {
				assertTrue(value.isTextual(), "computed numeric proof entries must be strings");
				computedVariables.add(value.textValue());
			});
			JsonNode order = null;
			OrderSpec orderSpec = fixture.order(index).orElse(null);
			if (orderSpec != null) {
				String orderFile = orderSpec.file();
				assertEquals(orderFile, queryRecord.path("orderFile").asText(), "ordered query sidecar " + index);
				byte[] orderBytes = requiredResource(fixture, "queries/" + orderFile);
				assertEquals(sha256(orderBytes), queryRecord.path("orderSha256").asText(),
						"ordered query sidecar SHA-256 " + index);
				order = JSON.readTree(orderBytes);
				assertEquals(index, requiredInt(order, "queryIndex"), "order file query identity " + index);
				if (orderSpec.kind() == ThemeOracleProfile.OrderKind.KEY_GROUPS) {
					assertEquals(orderSpec.keys()
							.stream()
							.map(key -> "?" + key)
							.collect(java.util.stream.Collectors.joining(" ")), order.path("orderBy").asText(),
							"ordered query key identity");
				}
			} else {
				assertFalse(queryRecord.has("orderFile") || queryRecord.has("orderSha256"),
						"unregistered order metadata at query " + index);
			}
			goldens.add(new QueryGolden(index, queryRecord.path("name").asText(),
					queryRecord.path("querySha256").asText(), bag, List.copyOf(computedVariables), orderSpec, order));
		}
		return new Bundle(dataset, List.copyOf(goldens));
	}

	private static void validateDefaultFixture(ThemeOracleProfile profile, JsonNode fixture, JsonNode dataset) {
		assertEquals(profile.fixtureId(), fixture.path("profile").asText(), "fixture profile identity");
		JsonNode scope = fixture.path("scope");
		assertEquals("default-graph-only", scope.path("graphs").asText(), "fixture graph scope");
		assertTrue(scope.path("directionalLiterals").isBoolean() && !scope.path("directionalLiterals").booleanValue(),
				"fixture directional literal scope");
		assertTrue(scope.path("tripleTerms").isBoolean() && !scope.path("tripleTerms").booleanValue(),
				"fixture triple-term scope");
		assertEquals(requiredCount(fixture, "statementCount"), requiredCount(dataset, "statements"),
				"fixture statement count");
	}

	private static void validateSocialFixtureCounts(JsonNode fixture, JsonNode dataset) {
		assertEquals("social-media-witness-v2", fixture.path("profile").asText(), "fixture profile identity");
		JsonNode scope = fixture.path("scope");
		assertEquals("default-graph-only", scope.path("graphs").asText(), "fixture graph scope");
		assertTrue(scope.path("directionalLiterals").isBoolean() && !scope.path("directionalLiterals").booleanValue(),
				"fixture directional literal scope");
		assertTrue(scope.path("tripleTerms").isBoolean() && !scope.path("tripleTerms").booleanValue(),
				"fixture triple-term scope");
		JsonNode counts = fixture.path("fixtureActualCounts");
		assertEquals(18, requiredCount(counts, "user"), "fixture users");
		assertEquals(3, requiredCount(counts, "post"), "fixture posts");
		assertEquals(requiredCount(fixture, "statementCount"), requiredCount(dataset, "statements"),
				"fixture statement count");
	}

	private static void validateFixtureCounts(JsonNode fixture, JsonNode dataset) {
		assertEquals(42, requiredLong(fixture, "seed"), "fixture seed identity");
		assertEquals("realestate-witness-overlay-v1", fixture.path("overlay").asText(), "fixture overlay identity");
		JsonNode scope = fixture.path("scope");
		assertEquals("default-graph-only", scope.path("graphs").asText(), "fixture graph scope");
		assertTrue(scope.path("directionalLiterals").isBoolean() && !scope.path("directionalLiterals").booleanValue(),
				"fixture directional literal scope");
		assertTrue(scope.path("tripleTerms").isBoolean() && !scope.path("tripleTerms").booleanValue(),
				"fixture triple-term scope");
		JsonNode requested = fixture.path("requestedCounts");
		assertEquals(4, requiredInt(requested, "districts"), "requested fixture districts");
		assertEquals(8, requiredInt(requested, "agents"), "requested fixture agents");
		assertEquals(3, requiredInt(requested, "amenities"), "requested fixture amenities");
		assertEquals(32, requiredInt(requested, "properties"), "requested fixture properties");
		for (String group : List.of("seededActualCounts", "fixtureActualCounts")) {
			for (String name : List.of("district", "agent", "amenity", "property", "viewing", "offer")) {
				requiredCount(fixture.path(group), name);
			}
		}
		long seeded = requiredCount(fixture, "seededStatementCount");
		long overlay = requiredCount(fixture, "overlayStatementCount");
		long total = requiredCount(fixture, "statementCount");
		assertTrue(seeded <= Long.MAX_VALUE - overlay, "fixture statement counts overflow");
		assertEquals(total, seeded + overlay, "fixture statement counts");
		assertEquals(total, requiredCount(dataset, "statements"), "dataset statement count");
	}

	private static int requiredInt(JsonNode node, String field) {
		JsonNode value = node.get(field);
		assertTrue(value != null && value.isIntegralNumber() && value.canConvertToInt(),
				"required integer field " + field);
		return value.intValue();
	}

	private static long requiredLong(JsonNode node, String field) {
		JsonNode value = node.get(field);
		assertTrue(value != null && value.isIntegralNumber() && value.canConvertToLong(),
				"required integer field " + field);
		return value.longValue();
	}

	private static long requiredCount(JsonNode node, String field) {
		long value = requiredLong(node, field);
		assertTrue(value >= 0, "negative count " + field);
		return value;
	}

	private static byte[] requiredResource(String name) throws IOException {
		return requiredResource(ThemeOracleProfile.REAL_ESTATE, name);
	}

	private static byte[] requiredResource(ThemeOracleProfile fixture, String name) throws IOException {
		try (InputStream input = LmdbRealEstateExactBagParityTest.class
				.getResourceAsStream(fixture.resourceRoot() + name)) {
			if (input == null) {
				throw new AssertionError("required " + fixture.theme() + " oracle resource is missing: "
						+ fixture.resourceRoot() + name);
			}
			return input.readAllBytes();
		}
	}

	private static void loadDataset(SailRepository repository, byte[] dataset, ThemeOracleProfile fixture)
			throws IOException {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(new ByteArrayInputStream(dataset), fixture.namespace(), RDFFormat.NQUADS);
		}
	}

	private static ObservedResult evaluate(SailRepository repository, String query, boolean nativeEngine,
			int queryIndex, String arm, ThemeOracleProfile fixture) {
		String previous = System.getProperty(NATIVE_ENGINE_PROPERTY);
		NativeExecutionObservation.Capture capture = NativeExecutionObservation.begin(512, 128);
		try {
			System.setProperty(NATIVE_ENGINE_PROPERTY, Boolean.toString(nativeEngine));
			List<String> variables;
			ArrayList<Row> rows = new ArrayList<>();
			try (NativeExecutionObservation.Scope ignored = capture.enter()) {
				try (SailRepositoryConnection connection = repository.getConnection();
						TupleQueryResult result = connection.prepareTupleQuery(QueryLanguage.SPARQL, query)
								.evaluate()) {
					variables = List.copyOf(result.getBindingNames());
					while (result.hasNext()) {
						var bindingSet = result.next();
						ArrayList<Value> detached = new ArrayList<>(variables.size());
						for (String variable : variables) {
							Value value = bindingSet.getValue(variable);
							detached.add(value == null ? null : detach(value));
						}
						rows.add(new Row(detached));
					}
				}
			} catch (RuntimeException failure) {
				throw new AssertionError(fixture.theme() + " query " + queryIndex + " failed in "
						+ (nativeEngine ? "LMDB native" : "generic RDF4J") + " evaluation", failure);
			}
			NativeExecutionObservation.Receipt receipt = capture.snapshot();
			reportObservation(queryIndex, arm, receipt, fixture);
			assertTrue(receipt.coverage() != NativeExecutionObservation.Coverage.TRUNCATED,
					"observation truncated for " + fixture.theme() + " query " + queryIndex + " arm " + arm);
			return new ObservedResult(variables, List.copyOf(rows), SolutionBagCodec.fromRows(variables, rows));
		} finally {
			if (previous == null) {
				System.clearProperty(NATIVE_ENGINE_PROPERTY);
			} else {
				System.setProperty(NATIVE_ENGINE_PROPERTY, previous);
			}
		}
	}

	@FunctionalInterface
	private interface EvaluationRunner {
		ObservedResult evaluate(SailRepository repository, String query, boolean nativeEngine, int queryIndex,
				String arm, ThemeOracleProfile fixture);
	}

	private static void reportObservation(int queryIndex, String arm, NativeExecutionObservation.Receipt receipt,
			ThemeOracleProfile fixture) {
		long rowStarted = receipt.events()
				.stream()
				.filter(event -> event.regionKind() == NativeExecutionObservation.RegionKind.ROW
						&& event.phase() == NativeExecutionObservation.Phase.STARTED)
				.count();
		long rowCompleted = receipt.events()
				.stream()
				.filter(event -> event.regionKind() == NativeExecutionObservation.RegionKind.ROW
						&& event.phase() == NativeExecutionObservation.Phase.COMPLETED)
				.count();
		System.out.println(fixture.theme() + "_OBSERVATION query=" + queryIndex + " arm=" + arm
				+ " coverage=" + receipt.coverage()
				+ " row=" + receipt.coverage(NativeExecutionObservation.RegionKind.ROW)
				+ " rowStarted=" + rowStarted + " rowCompleted=" + rowCompleted
				+ " group=" + receipt.coverage(NativeExecutionObservation.RegionKind.GROUP)
				+ " other=" + receipt.coverage(NativeExecutionObservation.RegionKind.OTHER)
				+ " borrowed=UNOBSERVED generic=UNOBSERVED link=" + receipt.selectedExecutionLink()
				+ " events=" + receipt.events().size());
	}

	private static Value detach(Value value) {
		if (value instanceof IRI iri) {
			return VALUE_FACTORY.createIRI(iri.stringValue());
		}
		if (value instanceof BNode bNode) {
			return VALUE_FACTORY.createBNode(bNode.getID());
		}
		if (value instanceof Literal literal) {
			String language = literal.getLanguage().orElse(null);
			Literal reconstructed;
			try {
				if (language != null) {
					reconstructed = literal.getBaseDirection() == Literal.BaseDirection.NONE
							? VALUE_FACTORY.createLiteral(literal.getLabel(), language)
							: VALUE_FACTORY.createLiteral(literal.getLabel(), language, literal.getBaseDirection());
				} else {
					reconstructed = VALUE_FACTORY.createLiteral(literal.getLabel(),
							VALUE_FACTORY.createIRI(literal.getDatatype().stringValue()));
				}
			} catch (IllegalArgumentException failure) {
				throw new AssertionError("invalid literal metadata during detachment", failure);
			}
			if (!literal.getLabel().equals(reconstructed.getLabel())
					|| !literal.getDatatype().stringValue().equals(reconstructed.getDatatype().stringValue())
					|| !literal.getLanguage()
							.map(tag -> tag.toLowerCase(Locale.ROOT))
							.equals(reconstructed.getLanguage().map(tag -> tag.toLowerCase(Locale.ROOT)))
					|| literal.getBaseDirection() != reconstructed.getBaseDirection()) {
				throw new AssertionError("literal metadata changed during detachment: " + literal);
			}
			return reconstructed;
		}
		if (value instanceof TripleTerm triple) {
			return VALUE_FACTORY.createTripleTerm((Resource) detach(triple.getSubject()),
					(IRI) detach(triple.getPredicate()), detach(triple.getObject()));
		}
		throw new IllegalArgumentException("unsupported result value for detached oracle bag: " + value.getClass());
	}

	private static void assertBagsEqual(Bag expected, Bag actual, String context) {
		assertTrue(SolutionBagCodec.isomorphic(expected, actual), context
				+ " exact typed duplicate-preserving bag mismatch; expected=" + SolutionBagCodec.encode(expected)
				+ "; actual=" + SolutionBagCodec.encode(actual));
	}

	private static void assertJenaBagsEquivalent(Bag expected, Bag actual, ComputedNumericBagPolicy.Plan policy,
			String context) {
		assertTrue(ComputedNumericBagPolicy.equivalent(expected, actual, policy), context
				+ " computed-numeric value-equivalence bag mismatch; expected=" + SolutionBagCodec.encode(expected)
				+ "; actual=" + SolutionBagCodec.encode(actual));
	}

	private static void assertOrderIfPinned(QueryGolden golden, ObservedResult actual, String context) {
		OrderSpec spec = golden.orderSpec();
		if (spec == null) {
			return;
		}
		switch (spec.kind()) {
		case PRICE_AND_IRI -> {
			assertEquals(2, spec.queryIndex(), "price/IRI order contract requires q2");
			List<String> expected = new ArrayList<>();
			golden.order().path("propertyIris").forEach(value -> expected.add(value.textValue()));
			assertEquals(expected, orderedIriKeys(actual, "p"), context + " q2 total price/IRI order");
		}
		case KEY_GROUPS -> {
			List<String> expected = new ArrayList<>();
			golden.order().path("groups").forEach(group -> expected.add(group.textValue()));
			assertEquals(expected, keyOrderGroups(actual, spec),
					context + " order-key group sequence; equal-key rows remain unordered");
		}
		}
	}

	private static List<String> orderedIriKeys(ObservedResult result, String variable) {
		int index = result.variables().indexOf(variable);
		assertTrue(index >= 0, "ordered REAL_ESTATE result must project ?" + variable);
		return result.rows().stream().map(row -> {
			Value value = row.values().get(index);
			assertTrue(value instanceof IRI, "q2 ordered key ?p must be an IRI");
			return value.stringValue();
		}).toList();
	}

	private static List<String> keyOrderGroups(ObservedResult result, OrderSpec spec) {
		List<Integer> positions = spec.keys().stream().map(result.variables()::indexOf).toList();
		assertTrue(positions.stream().allMatch(position -> position >= 0), "q11 must project its order keys");
		ArrayList<String> groups = new ArrayList<>();
		Row previous = null;
		for (Row resultRow : result.rows()) {
			List<Value> keyValues = positions.stream().map(resultRow.values()::get).toList();
			spec.requireSupportedGroupKeys(keyValues);
			Row key = new Row(keyValues);
			if (!key.equals(previous)) {
				groups.add(SolutionBagCodec.encode(
						SolutionBagCodec.fromRows(spec.keys(), List.of(key))));
				previous = key;
			}
		}
		return List.copyOf(groups);
	}

	private static String sha256(byte[] bytes) {
		try {
			return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));
		} catch (NoSuchAlgorithmException impossible) {
			throw new AssertionError(impossible);
		}
	}

